// 1) Find the model's text, no matter where n8n put it
function findText(obj) {
  if (typeof obj === 'string') return obj;

  const picks = [];
  const push = v => { if (typeof v === 'string' && v.trim()) picks.push(v); };

  // Common paths across n8n LLM builds
  push(obj.text);
  push(obj.output_text);
  push(obj.data);
  push(obj.completion);
  push(obj.output);
  if (obj.message?.text) push(obj.message.text);
  if (Array.isArray(obj.messages) && obj.messages[0]?.text) push(obj.messages[0].text);

  // Gemini raw candidates shape (safely join parts)
  try {
    const parts = obj.candidates?.[0]?.content?.parts || [];
    const joined = parts.map(p => p.text).filter(Boolean).join('\n');
    push(joined);
  } catch (e) {}

  // Sometimes the payload is nested under data.*
  if (obj.data && typeof obj.data === 'object') {
    push(obj.data.text);
    push(obj.data.output_text);
    push(obj.data.completion);
  }

  // Fallback: stringify the whole thing so we can try to carve JSON out
  return picks[0] ?? JSON.stringify(obj);
}

// 2) Clean the string and extract the JSON substring
function extractJsonString(s) {
  s = String(s ?? '').trim();
  // Strip ```json fences if the model added them
  s = s.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
  // If not starting with {, try to slice first {...} block
  if (!s.startsWith('{')) {
    const i = s.indexOf('{');
    const j = s.lastIndexOf('}');
    if (i !== -1 && j !== -1 && j > i) s = s.slice(i, j + 1);
  }
  return s;
}

const rawText = findText($json);
const jsonStr = extractJsonString(rawText);

let parsed;
try {
  parsed = JSON.parse(jsonStr);
} catch (e) {
  throw new Error(
    'Could not parse JSON from model output.\n' +
    'First 400 chars were:\n' + (rawText || '').slice(0, 400)
  );
}

// 3) Minimal schema checks
['events', 'snack_changes', 'allergy_changes', 'notices'].forEach(k => {
  if (k in parsed && !Array.isArray(parsed[k])) {
    throw new Error(`Field ${k} must be an array. Got: ${typeof parsed[k]}`);
  }
});

return [{ json: parsed }];

// === Helpers ===============================================================
function parseWeekRange(weekText) {
  const months = {'Jan.':0,'Feb.':1,'Mar.':2,'Apr.':3,'May':4,'Jun.':5,'Jul.':6,'Aug.':7,'Sep.':8,'Sept.':8,'Oct.':9,'Nov':10,'Dec.':11};
  const cleaned = String(weekText||'').replace(/\(.+?\)/g,'').replace(/\s+/g,' ').trim();
  const m = cleaned.match(/([A-Za-z]{3,}\.?)\s*(\d{1,2})\s*[-–]\s*([A-Za-z]{3,}\.?)?\s*(\d{1,2})/);
  if (!m) return null;
  const m1 = (m[1].replace(/\.$/,'') + '.'); const d1 = +m[2];
  const m2 = m[3] ? (m[3].replace(/\.$/,'') + '.') : m1; const d2 = +m[4];
  const year = new Date().getFullYear();
  const start = new Date(year, months[m1], d1);
  const end   = new Date(year, months[m2], d2, 23,59,59);
  return (isNaN(start)||isNaN(end)) ? null : { start, end };
}

// Collect items from ALL connected inputs (0..7) and flatten
const allItems = [];
for (let i = 0; i < 8; i++) {
  try { allItems.push(...$items(i).map(it => it.json)); } catch (_) {}
}

// Nothing came in?
if (!allItems.length) {
  return [{ json: { error: 'No inputs reached this node. Run the whole workflow (not just this step), or add a Merge (wait for both).' } }];
}

// Classify every item by shape (no assumptions about order or counts)
let extractor = null;
const calendar = [];
const snackRows = [];
const allergyRows = [];

for (const obj of allItems) {
  if (!obj || typeof obj !== 'object') continue;

  // Extractor JSON (has the 4 arrays)
  if (!extractor && 'events' in obj && 'snack_changes' in obj && 'allergy_changes' in obj) {
    extractor = obj;
    continue;
  }

  // Calendar event (summary/id plus start/end)
  if ((obj.summary || obj.id) && (obj.start || obj.end)) {
    calendar.push(obj);
    continue;
  }

  // Sheets rows
  if ('Week' in obj || 'Child' in obj) snackRows.push(obj);
  if ('Allergy' in obj) allergyRows.push(obj);
}

if (!extractor) {
  // Helpful debug: show the first item keys we saw
  return [{
    json: {
      error: 'Extractor JSON missing',
      hint: 'Ensure the output of "Validate JSON" is connected into the Merge that feeds this node.',
      sawItems: allItems.slice(0,3).map(o => Object.keys(o))
    }
  }];
}

// Map snack rows -> [{week, child, range, ...}]
const snack = snackRows
  .map(r => ({ week: String(r.Week ?? '').trim(), child: String(r.Child ?? '').trim() }))
  .filter(r => r.week);

const validSnack = snack
  .filter(r => r.child && !/SCHOOL CLOSED|NO INSTRUCTION/i.test(r.week))
  .map(r => ({ ...r, range: parseWeekRange(r.week) }));

// Compute "next Monday" assignee
const today = new Date();
const nextMon = new Date(today);
nextMon.setDate(today.getDate() + ((8 - today.getDay()) % 7));

const nextSnack = validSnack.find(r => r.range && nextMon >= r.range.start && nextMon <= r.range.end) || null;

// Build snack change proposals
const snackChanges = (extractor.snack_changes || []).map(ch => {
  const weekText = String(ch.week_text || '').replace(/\s+/g,' ').trim();
  let target = snack.find(r => r.week.replace(/\s+/g,' ').trim() === weekText);

  if (!target && weekText) {
    const parsed = parseWeekRange(weekText);
    if (parsed) target = validSnack.find(r => r.range && r.range.start.getTime() === parsed.start.getTime());
  }
  return { type: 'snack', targetWeek: target?.week || ch.week_text || '', newChild: ch.child || '' };
});

// Allergy set-diff (class-wide list)
const adds    = (extractor.allergy_changes || []).filter(x => x.op === 'add').map(x => x.item);
const removes = (extractor.allergy_changes || []).filter(x => x.op === 'remove').map(x => x.item);

return [{
  json: {
    nextSnack,
    calendar,
    proposed: {
      events: extractor.events || [],
      snack: snackChanges,
      allergies: { adds, removes }
    },
    debug: {
      counts: { allItems: allItems.length, calendar: calendar.length, snackRows: snackRows.length, allergyRows: allergyRows.length }
    }
  }
}];

// Use workflow static data as a tiny KV store
const store = $getWorkflowStaticData('global');
store.pending = store.pending || {};  // id -> { created, execId }

function makeToken(execId, ttlHours=72) {
  const token = (Math.random().toString(36).slice(2) + Date.now().toString(36));
  store.pending[token] = { created: Date.now(), execId, exp: Date.now() + ttlHours*3600*1000 };
  return token;
}

const execId = $execution.id; // current execution id
const token = makeToken(execId);

const approveUrl = `${$execution.resumeUrl}`.replace('/webhook-waiting/', '/webhook/')  // ensure /webhook/ base
  .replace(/\/[^/]*$/, '/room-parent/approve') + `?token=${encodeURIComponent(token)}`;
const rejectUrl = approveUrl.replace('/approve', '/reject');

return [{ json: { approveUrl, rejectUrl, token } }];

const store = $getWorkflowStaticData('global');
const token = $json.query.token;
const entry = token && store.pending && store.pending[token];
if (!entry) throw new Error('Invalid token');
if (Date.now() > entry.exp) { delete store.pending[token]; throw new Error('Token expired'); }

// Mark approved and pass the execId to the next node
const execId = entry.execId;
delete store.pending[token];
return [{ json: { approved: true, execId } }];

const store = $getWorkflowStaticData('global');
const token = $json.query.token;
const entry = token && store.pending && store.pending[token];
if (!entry) throw new Error('Invalid token');
if (Date.now() > entry.exp) { delete store.pending[token]; throw new Error('Token expired'); }

// Mark rejected and pass the execId to the next node
const execId = entry.execId;
delete store.pending[token];
return [{ json: { rejected: true, execId } }];

const data = typeof $json.body === 'object' && $json.body !== null ? $json.body : $json
const secret = typeof data.secret === 'string' ? data.secret.trim() : ''
if (!secret) {
  throw new Error('Missing secret in request body (expected JSON {"secret":"..."})')
}
const store = $getWorkflowStaticData('global')
store.approvalsHmacSecret = secret
return [{ json: { status: 'stored' } }]
